def rect(x,y,w,h,t='',sz=9,fill='#fff',dash=False):
    d=' stroke-dasharray="3 2"' if dash else ''
    b=f'<rect x="{x}" y="{y}" width="{w}" height="{h}" fill="{fill}" stroke="#111"{d}/>'
    if t: b+=T(x+w/2,y+h/2+3,t,sz,'middle',700)
    return b
def suite():
    b=T(250,12,'TCP/IP Protocol Sube',9,'middle',700)+T(5,30,'DARPA layers',9,'start',700)
    b+=rect(5,40,70,50,'Application Layer')+rect(5,98,70,40,'Transport Layer')+rect(5,148,70,45,'Internet Layer')+rect(5,200,70,50,'Network Interface Layer',8)
    for i,t in enumerate(['HTTP','FTP','SMTP','DNS','RIP','SNMP']): b+=rect(85+i*50,40,44,50,t)
    b+=rect(85,98,150,40,'TCP',11)+rect(245,98,150,40,'UDP',11)
    b+=rect(85,148,150,50,'')+T(160,165,'IGMP  ICMP',8,'middle',700)+T(160,190,'ARP   IP (IPv4)',8,'middle',700)+rect(245,148,150,50,'')+T(320,165,'ND  MLD  ICMPv6',8,'middle',700)+T(320,190,'IPv6',9,'middle',700)
    b+=rect(85,205,70,45,'Ethernet',8,'#fff',True)+rect(165,205,70,45,'802.11 wireless LAN',7,'#fff',True)+rect(245,205,70,45,'Frame Relay',8,'#fff',True)+rect(325,205,70,45,'ATM',9,'#fff',True)
    return svg(410,260,'TCP/IP protocol suite: application, transport, internet and network interface layers with their protocols',b)
def stack():
    b=T(100,12,'Host (your laptop)',9,'middle',700)+T(280,12,'Target (webserver)',9,'middle',700)
    ls=['Application Layer (HTTP)','Transport Layer (TCP)','Network Layer (IP)','Data Link Layer']
    for k,t in enumerate(ls):
        y=25+k*50
        b+=rect(30,y,150,34,t,9,'#d9f0c0')+rect(210,y,150,34,t,9,'#d9f0c0')
    b+=rect(30,225,330,22,'Media for data transfer (e.g. Ethernet)',9,'#d33')
    return svg(390,255,'Data passing down the layers of the host and up the layers of the target web server',b)
